import dayjs from 'dayjs';
import 'dayjs/locale/es';
import utc from 'dayjs/plugin/utc';
import timezonePlugin from 'dayjs/plugin/timezone';
import { Locales } from '@getvim/translate';
import { CommonFormats } from './commonFormats';

dayjs.extend(utc);
dayjs.extend(timezonePlugin);

export const date = (
  fullDate,
  timezone,
  locale = Locales.en,
  format = CommonFormats.SHORT_NAMING_DATE,
) => dayjs.utc(fullDate).tz(timezone).locale(locale).format(format);

export const time = (fullDate: string, timezone: string, format = CommonFormats.AM_PM_TIME) => {
  if (format === CommonFormats.AM_PM_TIME) {
    return new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      hour12: true,
      minute: 'numeric',
      timeZone: timezone,
    }).format(dayjs.utc(fullDate).toDate());
  }
  return dayjs.utc(fullDate).tz(timezone).format(format);
};

export const getFormattedDateString = (
  fullDate: string,
  locale = Locales.en,
  format = CommonFormats.SHORT_NAMING_DATE,
): string => dayjs(fullDate).locale(locale).format(format);
